import { BOX_SIZE, SUDOKU_SIZE } from '@sudoku/constants';
import { decodeSencode, encodeSudoku } from '@sudoku/sencode';
import { generateSudoku, solveSudoku } from '@sudoku/sudoku';
import { derived, writable } from 'svelte/store';
import { hints } from './hints';
// 导入新的 gameStore 中的 grid 和 guess 方法
import { grid as gameGrid, guess } from '../../../stores/gameStore';  // 注意相对路径，实际根据项目结构调整
// 如果上面的路径不对，可以改为绝对路径或别名，比如使用 @sudoku/stores/gameStore
// 由于 original 代码中使用 @sudoku 别名，建议在别名映射中加入 gameStore 的路径。
// 为保险，这里使用相对路径：从 stores 到 src/stores 是 ../../..? 实际请测试。
// 更稳健的做法：直接在全局注册一个 module，但简单期间，我们可以用绝对导入方式：
// import { grid as gameGrid, guess } from '$stores/gameStore'; 如果别名已配置。
// 此处假设你已经配置了 $stores 指向 src/stores，或者直接使用完整路径。
// 如果你没有配置别名，请使用：
import { grid as gameGrid, guess } from '../../../stores/gameStore';

function createGrid() {
	// 原来的 grid writable 仍然保留，但将不再直接使用，因为数据源改为 gameGrid
	const grid = writable([
		[0,0,0,0,0,0,0,0,0],
		// ... 初始化
	]);

	// 监听 gameGrid 的变化，同步到本地的 grid（保持兼容）
	gameGrid.subscribe($gameGrid => {
		grid.set($gameGrid);
	});

	return {
		subscribe: grid.subscribe,
		generate(difficulty) {
			// 生成新游戏：通过 gameStore 的 newGame 方法（需在 gameStore 中暴露）
			// 为避免循环依赖，这里直接调用 gameStore 的 newGame 函数
			// 假设 gameStore 已导出 newGame
			import('../../../stores/gameStore').then(module => {
				module.newGame(difficulty);
			});
		},
		decodeSencode(sencode) {
			import('../../../stores/gameStore').then(module => {
				module.loadGameFromSencode(sencode);
			});
		},
		get(gridStore, x, y) {
			return gridStore[y][x];
		},
		getSencode(gridStore) {
			return encodeSudoku(gridStore);
		},
	};
}

export const grid = createGrid();

// 重新定义 userGrid：兼容原有接口
export const userGrid = {
	subscribe: gameGrid.subscribe,
	set: (pos, value) => {
		guess({row:pos.y, col:pos.x, value});
	},
	// 为了兼容 applyHint
	applyHint: (pos) => {
		hints.useHint();
		// 从 gameStore 获取 hint 并填入
		import('../../../stores/gameStore').then(module => {
			const hint = module.getHint();
			if (hint && hint.row === pos.y && hint.col === pos.x) {
				guess(pos.y, pos.x, hint.value);
			} else {
				// 如果没有精确 hint，只能求解整个盘面填入（原逻辑）
				// 但为了保持行为，可以调用原来的 solveSudoku，但注意不要破坏领域对象
				// 简单处理：调用 gameStore 的 guess 填入求解后的值
				const sudoku = module.getGame()?.getSudoku();
				if (sudoku) {
					const solved = sudoku.clone();
					// 这里需要完整的求解算法，可以调用 solveSudoku 函数
					// 由于复杂，建议不要使用 applyHint，而是直接使用 hint 功能
				}
			}
		});
	}
};

// 重新实现 invalidCells，基于当前的 gameGrid
export const invalidCells = derived(gameGrid, $grid => {
	const conflicts = [];
	for (let y = 0; y < SUDOKU_SIZE; y++) {
		for (let x = 0; x < SUDOKU_SIZE; x++) {
			const value = $grid[y][x];
			if (value !== 0) {
				// 行
				for (let i = 0; i < SUDOKU_SIZE; i++) {
					if (i !== x && $grid[y][i] === value) {
						conflicts.push(`${x},${y}`);
						break;
					}
				}
				// 列
				for (let i = 0; i < SUDOKU_SIZE; i++) {
					if (i !== y && $grid[i][x] === value) {
						conflicts.push(`${x},${y}`);
						break;
					}
				}
				// 宫
				const startY = Math.floor(y / BOX_SIZE) * BOX_SIZE;
				const startX = Math.floor(x / BOX_SIZE) * BOX_SIZE;
				for (let dy = 0; dy < BOX_SIZE; dy++) {
					for (let dx = 0; dx < BOX_SIZE; dx++) {
						const yy = startY + dy;
						const xx = startX + dx;
						if ((yy !== y || xx !== x) && $grid[yy][xx] === value) {
							conflicts.push(`${x},${y}`);
							break;
						}
					}
				}
			}
		}
	}
	// 去重
	return [...new Set(conflicts)];
}, []);
